{
  "sop_id": "SOP-013",
  "title": "Bill of Quantities (BOQ) Review",
  "steps": [
    {
      "step_id": "S1",
      "name": "Create and validate BOQ",
      "role": "Executor",
      "type": "intake"
    },
    {
      "step_id": "S2",
      "name": "Check BOQ template checklist",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S3",
      "name": "Check quantities and rates",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S4",
      "name": "Summarise variance and submit",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "A1",
      "name": "Incharge approval",
      "role": "Incharge",
      "type": "approval"
    },
    {
      "step_id": "R1",
      "name": "Rejection and resubmission",
      "role": "Executor",
      "type": "rework"
    }
  ],
  "approvals": [
    {
      "stage": "Incharge",
      "condition": "always"
    },
    {
      "stage": "Lead",
      "condition": "exceptions only"
    }
  ],
  "dependencies": [
    {
      "dep_id": "D1",
      "provider": "Operations",
      "item": "Drawings and take-off confirmation",
      "parallel_group": "true"
    }
  ],
  "rework_reasons": [
    "Wrong quantity",
    "Amount mismatch",
    "Incorrect category",
    "Required document missing"
  ],
  "first_pass_yield_target": 0.9
}
